"""Generate reader-facing reports/figures from canonical results, without fitting."""
from pathlib import Path
import json, datetime, hashlib, csv, collections, re, xml.etree.ElementTree as ET
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
from analyze import read, dump, P, write_csv, sha

def coeff(m, k):
    return next((v for v in m['coefficients'] if v['term'] == k))

def license_name(s):
    try:
        root = ET.parse(s['source']).getroot()
        p = root.find('.//permissions')
        urls = [v for e in p.iter() for (k, v) in e.attrib.items() if 'href' in k and 'creativecommons.org' in v]
        if urls:
            return urls[0]
        content = ET.tostring(p, encoding='unicode')
        urls = re.findall('https?://creativecommons.org/licenses/[^\\s<)]+', content)
        if urls:
            return urls[0]
        txt = ' '.join(p.itertext())
        if 'Attribution-NonCommercial-ShareAlike 4.0' in txt:
            return 'CC BY-NC-SA 4.0 (local permissions text)'
        if 'Creative Commons Attribution License' in txt:
            return 'CC BY (version unspecified in local permissions)'
    except (ET.ParseError, OSError, AttributeError):
        pass
    try:
        txt = Path(s['source']).read_text()
        urls = re.findall('https?://creativecommons.org/licenses/[^\\s<)]+', txt)
        if urls:
            return urls[0]
    except OSError:
        pass
    return 'UNKNOWN: inspect original permissions'

def figures(r1, r2):
    plt.rcParams.update({'font.size': 10, 'axes.spines.top': False, 'axes.spines.right': False, 'savefig.dpi': 180})
    d = read('NORMALIZED_DATA.json')
    (fig, ax) = plt.subplots(1, 2, figsize=(13, 5.5))
    for (study, color, marker) in [('PMC10246932', '#196b91', 'o'), ('PMC10721348', '#cc6b26', 's')]:
        a = sorted([r for r in d['cement'] if r['study'] == study], key=lambda r: r['CAD_um'])
        x = [r['CAD_um'] for r in a]
        y = [r['outcome'] for r in a]
        se = np.sqrt([r['variance'] for r in a])
        ax[0].errorbar(x, y, yerr=1.96 * se, fmt=marker + '-', color=color, capsize=3, label=study)
    ax[0].set(xlabel='Configured internal CAD spacer (µm)', ylabel='Measured marginal gap (µm)', title='Marginal dose studies (2 primary reports)')
    ax[0].legend(frameon=False)
    ax[0].text(0.02, 0.02, 'PER_SURFACE_REGION\nBars: conditional 95% mean intervals\nSD basis/covariance unresolved', transform=ax[0].transAxes, fontsize=8)
    a = [r for r in r2['contrasts'] if r['dataset'] == 'crown']
    for (i, r) in enumerate(a):
        se = np.sqrt(r['variance'])
        ax[1].errorbar(r['estimate'], i, xerr=1.96 * se, fmt='o', color='#196b91' if r['study'] == 'PMC10817558' else '#cc6b26', capsize=3)
    labels = [r['stratum'].replace('PMC10817558|', 'PMC10817558 | ').replace('PMC7274823|', 'PMC7274823 | ').replace('|UNKNOWN', '').replace('zirconia_unspecified', 'Zr unspecified') for r in a]
    ax[1].set_yticks(range(len(a)), labels)
    ax[1].axvline(2, color='#333333', ls='--', label='Declared thickness² proxy')
    ax[1].set(xlabel='log(force ratio) / log(thickness ratio)', title='Within-study crown thickness contrasts')
    ax[1].invert_yaxis()
    ax[1].legend(frameon=False, loc='lower right')
    fig.suptitle('Local information is estimable; cross-laboratory design effects remain unresolved', fontsize=13)
    fig.text(0.5, 0.015, 'Crown: PER_TOOTH group means. Six contrasts from only two studies; conditional intervals do not establish transfer.', ha='center', fontsize=9)
    fig.tight_layout(rect=[0, 0.045, 1, 0.94])
    fig.savefig(P / 'META_RESULTS.png')
    fig.savefig(P / 'META_RESULTS.pdf')
    plt.close(fig)
    (fig, axs) = plt.subplots(1, 2, figsize=(12, 5))
    for (ax, (name, v)) in zip(axs, r1['funnel'].items()):
        a = v['study_summaries']
        x = np.array([r['value'] for r in a])
        se = np.array([r['se_upper_correlation1'] for r in a])
        center = float(np.mean(x))
        ax.scatter(x, se, c='#196b91')
        yy = np.linspace(0, max(se) * 1.2, 100)
        ax.plot(center - 1.96 * yy, yy, '--', color='#999999')
        ax.plot(center + 1.96 * yy, yy, '--', color='#999999')
        for r in a:
            right = r['value'] > center
            ax.annotate(r['cluster'].replace('PMC', '').replace('ElGhoul_fit_family', 'ElGhoul family'), (r['value'], r['se_upper_correlation1']), fontsize=7, xytext=(-4 if right else 4, 4), ha='right' if right else 'left', textcoords='offset points')
        ax.invert_yaxis()
        ax.set(title=f'Descriptive funnel: k={len(a)} source families', ylabel='Upper-correlation-bound SE', xlabel='Mean marginal gap − CAD (µm)' if name.startswith('cement') else 'Mean log(crown force in N)')
        ax.text(0.02, 0.02, f"Egger diagnostic p={v['egger']['p_two_sided']:.3f}\nFormal test withheld: k < 10; unlike estimands", transform=ax.transAxes, fontsize=8)
    fig.suptitle('Publication bias remains UNKNOWN', fontsize=13)
    fig.text(0.5, 0.01, 'POPULATION: selected study summaries; pooled arm covariance and common target effects are unavailable. Funnel shape is not a bias verdict.', ha='center', fontsize=8)
    fig.tight_layout(rect=[0, 0.03, 1, 0.94])
    fig.savefig(P / 'FUNNEL.png')
    fig.savefig(P / 'FUNNEL.pdf')
    plt.close(fig)
    (fig, axs) = plt.subplots(1, 2, figsize=(12, 9))
    flow = r1['flow']
    for (ax, kind) in zip(axs, ['cement', 'crown']):
        v = flow[kind]
        ax.set_axis_off()
        ax.set(xlim=(0, 1), ylim=(0, 1))
        ax.set_title('Cement fit' if kind == 'cement' else 'Crown fracture force', fontsize=13)
        entries = [(0.86, f"Local corpus records: {v['local_records']}\nAdditional local reports: {v['additional_local_primary_reports']}\nTotal identified locally: {v['total_identified_local_records']}"), (0.64, f"Inherited extracted reports: {v['inherited_extracted_reports']}\nEligibility unassessed / not extracted: {v['not_extracted_or_eligibility_not_assessed']}\nThese are NOT eligibility exclusions"), (0.43, f"Extracted group cells: {v['extracted_rows']}\nRows outside primary model: {v['extracted_rows'] - v['primary_rows']}\nRejection fraction: {100 * v['rejected_row_fraction']:.2f}%"), (0.21, f"Primary model: {v['primary_rows']} rows\n{v['primary_reports']} reports; " + ('9 conservative source families' if kind == 'cement' else '4 independent studies'))]
        for (yy, label) in entries:
            ax.add_patch(FancyBboxPatch((0.05, yy - 0.07), 0.9, 0.14, boxstyle='round,pad=0.012', facecolor='#edf4f8', edgecolor='#7a9bab'))
            ax.text(0.5, yy, label, ha='center', va='center', fontsize=10)
        for (a, b) in zip(entries, entries[1:]):
            ax.annotate('', xy=(0.5, b[0] + 0.085), xytext=(0.5, a[0] - 0.085), arrowprops={'arrowstyle': '->', 'color': '#607786'})
    fig.suptitle('Reconstructed PRISMA-style local secondary-synthesis flow', fontsize=14)
    fig.text(0.5, 0.035, 'Original database search/retrieval counts UNKNOWN. Targeted inherited selection, no dual screening or extraction.\nThis is a transparent partial flow, not a completed PRISMA systematic review.', ha='center', fontsize=10)
    fig.savefig(P / 'PRISMA_FLOW.png')
    fig.savefig(P / 'PRISMA_FLOW.pdf')
    plt.close(fig)

def main():
    r1 = read('RESULTS_R1.json')
    r2 = read('RESULTS_R2.json')
    r3 = read('RESULTS_R3.json')
    verify = read('VERIFICATION.json')
    figures(r1, r2)
    gd = r1['models']['cement_full']
    cd = r1['models']['crown_full']
    support_table = []
    for (name, m) in r1['models'].items():
        support_table.append(dict(model=name, rows=m['support']['n_rows'], study_families=m['support']['independent_clusters'], fixed_coefficients=m['support']['p_fixed'], rank=m['support']['rank'], tau2=m.get('tau2_study'), omega2=m.get('omega2_cell'), I2_percent=m.get('I2_total_percent'), confirmatory_support_pass=m['support']['confirmatory_support_pass'], resolution_level='POPULATION'))
    write_csv('MODEL_SUMMARY.csv', support_table)
    coefficients = [dict(model=name, resolution_level='POPULATION', **c) for (name, m) in r1['models'].items() for c in m.get('coefficients', [])]
    write_csv('COEFFICIENTS.csv', coefficients)
    data = read('NORMALIZED_DATA.json')
    exclusions = []
    for r in data['cement']:
        if not r['eligible']:
            exclusions.append(dict(dataset='cement', row_id=r['row_id'], study=r['study'], reason=r['exclusion_reason'], doi=r['doi'], locator=r['locator']))
    for r in data['crown']:
        if not r['thickness_eligible']:
            exclusions.append(dict(dataset='crown', row_id=r['row_id'], study=r['study'], reason=r['endpoint_exclusion'] or 'actual_crown_thickness_unknown', doi=r['doi'], locator=r['locator']))
    write_csv('ROW_EXCLUSIONS.csv', exclusions)
    publish = dict(claim_type='information_link', review_state='PENDING_INDEPENDENT_REVIEW', outcome='LOCAL_DESIGN_CONTRASTS_ESTIMABLE; TRANSFERABLE_FULL_ADJUSTED_META_REGRESSIONS_UNSUPPORTED; PUBLICATION_BIAS_UNKNOWN', study_counts=dict(cement=dict(raw_cells=148, raw_reports=11, primary_cells=84, primary_reports=10, primary_source_families=9), crown=dict(raw_cells=49, raw_reports=8, primary_cells=30, primary_reports=4, complete_endpoint_cells=45, complete_endpoint_reports=7)), requested_models=dict(cement=gd, crown=cd), rounds=dict(R1='RESULTS_R1.json', R2='RESULTS_R2.json', R3='RESULTS_R3.json'), within_study_contrasts=r2['contrasts'], fixture_identifiability=r3, holdout=r1['holdout'], publication_bias=r1['funnel'], external_referent=dict(kind='independent_measurement', locator='EXTRACTION_CEMENT.csv and EXTRACTION_CROWN.csv primary DOI/table/cell/source SHA256; WITHIN_STUDY_CONTRASTS.csv', compared_quantity='Published specimen-group mean regional cement gap (um) and full-crown fracture force (N)', refutes_us=True), external_numerical_control=read('STATSMODELS_CONTROL.json'), verification=dict(n_checks=verify['n_checks'], all_pass=verify['all_pass'], path='VERIFICATION.json'), resolution_level='POPULATION', native_evidence_levels=['PER_SURFACE_REGION', 'PER_TOOTH'], edges=[dict(source='EXTRACTION_CEMENT.csv', target='DENT-IF-RESTORATION-CEMENT-TOOTH', resolution_level='PER_SURFACE_REGION', time_scale='SIMULTANEOUS', status='PENDING_INDEPENDENT_REVIEW'), dict(source='EXTRACTION_CROWN.csv', target='DENT-MAT-RESTORATIVE-PSP', resolution_level='PER_TOOTH', time_scale='SIMULTANEOUS', status='PENDING_INDEPENDENT_REVIEW')], missing_cross_edge='Cement gap -> crown force cannot be joined across unpaired studies. Requires same crown, loading time, thickness, cement, film region and failure mode; do not infer a HANDOVER edge from table co-occurrence.', attrition=dict(reasons=collections.Counter((x['dataset'] + ':' + x['reason'] for x in exclusions)), fractions={k: v['rejected_row_fraction'] for (k, v) in r1['flow'].items()}), cost=dict(R1=r1['cost'], R2_seconds=r2['elapsed_seconds'], R3_seconds=r3['elapsed_seconds'], validation_seconds=verify['elapsed_seconds'], external_extraction_and_agent_reasoning='UNKNOWN', physical_measurements=0, questions=0), publication_readiness='METHODS_AND_ANALYSIS_DRAFT_ONLY; incomplete systematic search/screening, low study support and independent dual extraction pending', known_lineage_issue=read('LINEAGE_DRIFT.json'), phenomenological_debts=[dict(quantity='within-specimen regional covariance', replacement_measurement='Specimen-ID-linked repeated regional measurements and arm-level covariance'), dict(quantity='Gaussian study/cell exchangeability', replacement_measurement='Independent laboratory replication under matched fixture/material/thickness'), dict(quantity='CAD gap spatial reconstruction', replacement_measurement='Co-registered actual film map on each manufactured crown')])
    dump('results.json', publish)
    for round_id in ['R2', 'R3']:
        dump('DECOMPOSITION_' + round_id + '.json', dict(round=round_id, claim_type='information_link', timing_note='Equations/operations were specified in the frozen round PREREG before numerical exploration; this structured leaf supplement was emitted during delivery.', idea=read('PREREG_' + round_id + '.json')['capability'], operation=read('PREREG_' + round_id + '.json')['changed_operation'], leaves=[dict(name='primary_group_measurements_and_fixture_metadata', status='EXTERNALLY_MEASURED', provenance='Original DOI/table/paragraph/source SHA in extraction CSVs', stopping_argument='Published summary/protocol is finest available; specimen observations unavailable'), dict(name='contrast_cancellation_or_matrix_nullspace', status='DERIVED_UNDER_ASSUMPTIONS', equation='R2: difference/log-ratio cancels common study offsets; R3: X v=0 prevents distinct parameter estimates', stopping_argument='Finite-dimensional linear algebra and definition of endpoint contrast'), dict(name='sampling_covariance_and_transfer', status='UNKNOWN', provenance='No independent specimen-ID covariance or matched fixture replication', stopping_argument='Requires new paired measurements; metadata alone does not identify sampling dependence'), dict(name='random_effect_exchangeability', status='CONSTITUTIVE_CLOSURE', equation='Gaussian independent source intercept and residual cell effect', stopping_argument='Descriptive statistical closure; no microscopic fracture law inferred')], resolution_level='PER_SURFACE_REGION' if round_id == 'R2' else 'PER_TOOTH', time_scale='SIMULTANEOUS'))
    snapshots = {k: [{n: r[n] for n in ['row_id', 'held_cluster', 'status', 'prediction', 'pi95'] if n in r} for r in v['rows']] for (k, v) in r1['holdout'].items()}
    if not (P / 'FROZEN_PREDICTIONS.json').exists():
        dump('FROZEN_PREDICTIONS.json', dict(frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), scope='Retrospective holdout predictions frozen AFTER retrospective scoring; source observations already known. No claim of prospective or blinded measurement.', future_lab_prediction='UNKNOWN until local calibration and prospective protocol', input_manifest_sha256=sha(P / 'INPUT_MANIFEST.json'), predictions=snapshots))
        (P / 'FROZEN_PREDICTIONS.sha256').write_text(sha(P / 'FROZEN_PREDICTIONS.json') + '  FROZEN_PREDICTIONS.json\n')
    license_rows = []
    for s in read('SOURCE_PERMISSIONS.json'):
        license_rows.append(dict(study=s['study'], local_source=s['source'], license=license_name(s), source_sha256=s['sha256']))
    write_csv('LICENSES.csv', license_rows)
    ls = '\n'.join((f"| {r['study']} | {r['license']} |" for r in license_rows))
    gr = r1['holdout']['cement']['summary']
    cr = r1['holdout']['crown']['summary']
    README = f"# Cement fit and crown fracture force: what local literature can identify\n\nPublished group measurements now produce region-aware, study-aware estimates, uncertainty scenarios and local design contrasts. The requested full regressions are executable, but these selected data do not support a transferable adjusted design rule. No clinical recommendation is made.\n\nRun one command from this directory: `./run_all.sh`. The script uses the existing NumPy/SciPy/Matplotlib environment and installed system statsmodels, at most four threads, no GPU, no downloads. See [METHODS_DRAFT.md](METHODS_DRAFT.md) for the journal-facing methods and [META_RESULTS.pdf](META_RESULTS.pdf) for the primary figure.\n\n| Observable / analysis | Result | Resolution |\n|---|---|---|\n| Cement primary extraction | 84 of 148 cells; 10 papers, 9 conservative source families | PER_SURFACE_REGION group means |\n| Crown full material–thickness–angle model | 30 of 49 groups, 4 studies | PER_TOOTH group means |\n| Cement full REML heterogeneity | τ² study={gd['tau2_study']:.2f} µm²; ω² cell={gd['omega2_cell']:.2f} µm²; I² total={gd['I2_total_percent']:.2f}% | POPULATION, model conditional |\n| Crown full REML heterogeneity | τ² study={cd['tau2_study']:.5f} log(N)²; ω² cell={cd['omega2_cell']:.5f} log(N)²; I² total={cd['I2_total_percent']:.2f}% | POPULATION, model conditional |\n| Cement held-family error | {gr['study_balanced_RMSE']:.2f} µm vs CAD-identity proxy {gr['practice_study_balanced_RMSE']:.2f} µm; interval coverage {100 * gr['study_balanced_coverage']:.1f}% | PER_SURFACE_REGION; balanced over 9 source families |\n| Crown held-family error | {cr['study_balanced_RMSE']:.3f} log(N) vs thickness² proxy {cr['practice_study_balanced_RMSE']:.3f}; 16/30 groups scoreable, only 2 held studies | PER_TOOTH; restricted scoreable subset |\n| Marginal CAD endpoint response | −2.7625 and −1.1375 µm per +10 µm CAD; only 2 studies | PER_SURFACE_REGION |\n| Matched crown thickness endpoint exponents | 0.299–1.711; 6 contrasts from only 2 studies | PER_TOOTH |\n| Fixture vector | rank 6/8; diameter, speed and angle inseparable | PER_TOOTH fixture metadata |\n| Egger / publication bias | Descriptive funnels; 9 fit families and 7 crown studies; formal inference withheld | POPULATION |\n\nThe cement prediction gate fails. Crown prediction passes the frozen error/coverage gate on its **scoreable subset only**; 14 unscoreable groups are retained as UNKNOWN, so this is not whole-corpus performance. Every adjusted inferential support gate fails. The local contrast intervals are conditional on reported specimen-based SD and independent arms. R2 pooling does not make two studies a population design law.\n\n![Local measurements and thickness contrasts](META_RESULTS.png)\n\nPrimary external reference measurements are identified by DOI, table/paragraph, row and source hash in [EXTRACTION_CEMENT.csv](EXTRACTION_CEMENT.csv), [EXTRACTION_CROWN.csv](EXTRACTION_CROWN.csv) and [WITHIN_STUDY_CONTRASTS.csv](WITHIN_STUDY_CONTRASTS.csv). Examples: marginal CAD doses in [Suliman and Rayyan](https://doi.org/10.7759/cureus.38688), crown thickness contrasts in [Chen et al.](https://doi.org/10.3390/ma17020365) and [zirconia margin/thickness study](https://doi.org/10.1055/s-0040-1709342). These are published external group measurements, not a new prospective experiment.\n\nThe same-information numerical controls agree: independently evaluated dense REML and external statsmodels GLS on the actual retained observations. [VERIFICATION.json](VERIFICATION.json) contains {verify['n_checks']} passing checks and wrong-value probes. Agreement establishes implementation consistency, not scientific novelty or calibration validity.\n\n## What does not hold\n\nThis is a **selected local secondary synthesis with PRISMA-style reporting**, not a completed systematic review. The fit package contains 305 records but only 11 inherited extracted reports; the crown package contains 425 records plus 4 additional local reports, of which 8 were extracted. Eligibility of the remaining 294/421 records was not assessed. Original database search and retrieval counts are UNKNOWN. See [PRISMA_FLOW.pdf](PRISMA_FLOW.pdf), [SCREENING_LEDGER.csv](SCREENING_LEDGER.csv) and [PRISMA_CHECKLIST.csv](PRISMA_CHECKLIST.csv); unassessed records are not called exclusions. Independent duplicate extraction is pending.\n\nRows outside the primary models are 64/148 fit cells (43.24%) and 19/49 crown groups (38.78%). Reasons and locators are in [ROW_EXCLUSIONS.csv](ROW_EXCLUSIONS.csv). Different gap regions and endpoints stay separate. Actual thickness is not imputed from preparation reduction. The bridge paper's location-pooled SD is excluded; another inconsistent mean/SD cell is excluded. Two potentially shared fit papers are clustered together, with a drop-one-paper sensitivity.\n\nThe source audit caught a label/value concatenation: RelyX **U200** was attached to **2119.94 N**, producing **2002119.94 N** in the inherited extraction. R1 excludes that row. [EXTRACTION_CROWN_CORRECTED_R2.csv](EXTRACTION_CROWN_CORRECTED_R2.csv) repairs it using the original XML cell boundary, with provenance in [SOURCE_CORRECTION_R2.json](SOURCE_CORRECTION_R2.json). Original input snapshots remain intact. The correction is not a fitted adjustment.\n\nHigh I² does not establish a universal physical distribution. Sampling-SD basis and repeated-region covariance are unresolved; no-n and ρ=0.5/0.9 sensitivities are reported. The two dose studies observe only marginal gaps; axial/occlusal dose effects are UNKNOWN. The apparent angle effect bundles indenter, speed and support. A random study intercept cannot create missing independent fixture variation.\n\nAn exact first R1 result-hash predecessor was not retained before a replay; [LINEAGE_DRIFT.json](LINEAGE_DRIFT.json) records this limitation. Frozen input/protocol hashes and original source measurements remain intact. Later replays archive mutable outputs automatically. Frozen holdout predictions are explicitly retrospective and were saved after scoring; no prospective measurement or blind-validation claim is made.\n\n## Laboratory test and data rights\n\nThe next useful measurement is a randomized three-dose spacer sweep with all three regions on specimen-ID-linked crowns, followed by a held batch, plus a thickness × angle experiment on matched material, die, indenter and ageing. Record fracture origin. [NEXT_EXPERIMENT.md](NEXT_EXPERIMENT.md) defines these missing ports; it does not invent sample-size power without a covariance estimate. There is no paired cement-gap → fracture-force edge between the current unpaired studies.\n\nOnly published local literature group statistics are used; no geometry datasets or personal identifiers. Source licences below are read from original permissions; see [LICENSES.csv](LICENSES.csv). Original full texts are referenced locally, not republished. Redistribution and independent source review remain to be checked before journal submission.\n\n| Primary source | Permission URL read from local article |\n|---|---|\n{ls}\n\nStatus: PENDING_INDEPENDENT_REVIEW. Full cost: timed computation and memory are in results.json; inherited harvest/extraction and agent reading cost remain UNKNOWN. No physical measurements, user questions or paid external tools. All intermediates are below the 3 GB lane limit.\n"
    (P / 'README_DEMO.md').write_text(README)
    (P / 'RESULTS.md').write_text(README.split('## Laboratory test')[0] + '\nFull reader-facing package and licences: [README_DEMO.md](README_DEMO.md). Journal methods: [METHODS_DRAFT.md](METHODS_DRAFT.md).\n')
    methods = f"# Draft methods for journal review\n\n**Scope and registration.** We conducted a secondary quantitative synthesis of previously extracted, locally held full-text literature on restoration fit and full-contour crown fracture force. We froze analysis protocols and input checksums before fitting the present models (PREREG_R1, R2 and R3). Source values and previous lane outcomes were already known when these protocols were written; this was neither prospective registration nor blinded extraction. The study is not yet a systematic review. Reporting follows relevant [PRISMA 2020 items](https://www.prisma-statement.org/prisma-2020), with unavailable search, screening and independent-extraction items explicitly recorded rather than reconstructed from assumption.\n\n**Sources and selection.** The local fit literature package contained 305 unique records and the crown literature package 425. Four additional original crown reports were available through the predecessor extraction. No further datasets were downloaded. We reused the targeted extraction of 148 fit cells from 11 reports and 49 fracture-force groups from 8 reports. The original exhaustive database strategy, search totals and retrieval failure counts were unavailable. The 294 remaining fit records and 421 remaining crown records were not eligibility-assessed and were not classified as exclusions. We provide a record ledger and a reconstructed partial flow. Selection was inherited and non-systematic; publication and availability bias cannot be bounded by these records alone.\n\n**Extraction and eligibility.** For fit, the observational unit was a study-arm regional group mean in micrometres, retaining regional labels, configured internal and marginal spacers, material, CAD system, manufacturing process, seated state, measurement method, reported SD and specimen count. Primary regions were marginal, axial and occlusal. Absolute marginal discrepancy, cervical, pulpal, transition and overall internal quantities were retained separately. Location-pooled bridge SD and one internally inconsistent occlusal mean/SD cell were excluded from the primary fit model. The resulting sample comprised 84 cells from 10 reports. Two reports with potentially shared authors/methods and repeated summary values were conservatively grouped as one source family, yielding nine independent clusters; a drop-one-paper sensitivity was also fitted. This is a dependence precaution, not proof of duplicated specimens.\n\nFor fracture force, the observational unit was the arithmetic group mean full-crown force in newtons. We retained material class/product, reported actual crown thickness, loading angle, indenter diameter, crosshead speed, die, cement, abrasion and ageing where available. Preparation reduction was not substituted for crown thickness. Critical splitting loads were retained outside the primary full-crown endpoint. Unknown yttria class was retained as explicitly unspecified zirconia where the primary source identified zirconia. A product/5-mol% inconsistency was preserved as its own reported/conflicted category. Thirty groups from four independent studies had primary endpoint and actual thickness; 45 groups from seven studies were available for an endpoint-only secondary model. All source rows, reasons and failed extractions remain in the denominator.\n\n**Source verification.** Frozen inherited files and retained rows were bound to local original source SHA256 values and DOI/PMCID/table/paragraph locators. For fit, all inherited means and SDs were replayed against original expanded XML table cells, at an absolute tolerance of 0.011 source units. For crown data, mean/SD pairs were verified in the original tables or the explicitly identified Results paragraph; this does not substitute for independent duplicate extraction of every locator. The source audit identified one erroneous inherited flattened-text value: a cement label 'RelyX U200' had been concatenated with the next mean, producing 2002119.94 N instead of 2119.94 N (SD 205.93 N), [primary Table 3](https://doi.org/10.1186/s12903-023-03365-5). R1 excluded it. A separate version re-extracted the XML td boundary and retained both values and provenance. No original article or frozen raw input was edited.\n\n**Sampling model and transformations.** Fit outcomes were analysed in micrometres. Crown outcomes were log-transformed arithmetic means, log(mean N), not unobserved individual log-force means. Conditional sampling variances were SD²/n for fit and SD²/(n mean²) for crown means (first-order delta method). These calculations require specimen-level SD and independent sampling. Covariance of repeated regions on the same crown was unreported. Accordingly, we label all precision estimates conditional, exclude known location-pooled SD, and fit sampling-correlation scenarios ρ=0.5 and 0.9 within study/arm as well as a fit sensitivity using SD² without division by n. These are sensitivity scenarios, not measured correlations or repaired specimen-level estimates.\n\n**Meta-regression.** The fit fixed-effects design contained a within-study-centred CAD spacer term per 10 µm, a between-study CAD mean centred at 50 µm per 10 µm, region indicators, material indicators, broad CAD-system indicators and a cemented-state indicator. CAD was centred within the retained study rows; the two spacer sweeps therefore supply the within-study dose term. System families were 3Shape, Exocad, CEREC and Other; the last explicitly includes unknown system metadata and is not a calibrated homogeneous process. Reduced models removed material/system terms according to the frozen specification, not significance selection.\n\nThe crown fixed-effects design contained log(actual thickness), reported material categories and a 30-degree setup indicator. This indicator describes a bundled setup contrast and is not a causal angle effect. Secondary analysis removed thickness to describe all endpoint-eligible observations. We additionally expanded the physical fixture vector to indenter diameter and crosshead speed before fitting. On the complete source metadata, its matrix had rank 6 with 8 columns; a dataset-specific exact arithmetic alias links diameter, speed and angle flag. Thus these fixture components cannot be separated here. No dependent predictor was deleted to manufacture a full-rank physical-fixture model. Die and ageing remain additional unresolved sources of confounding.\n\nOutcomes followed y=Xβ+u_study+v_cell+e, with u~N(0,τ²), v~N(0,ω²), known conditional sampling covariance S, and V=S+τ²ZZ′+ω²I. Restricted maximum likelihood minimized one half of log|V|+log|X′V⁻¹X|+r′V⁻¹r using Cholesky factorization. The cell component allows residual within-study heterogeneity rather than forcing all variation into the reported sampling SD; it does not model measured specimen covariance. For the two singleton study-level spacer contrasts, the cell component was fixed at zero because separate study/cell variance components cannot be identified. Study intercepts were clustered at conservative source-family level. SVD checks preceded fitting; projected covariance-component ranks were retained. Model coefficients are descriptive associations in this selected corpus.\n\n**Uncertainty and heterogeneity.** We report conditional normal 95% coefficient intervals, separately labelled approximate cluster-sandwich intervals with k−1 Student-t degrees of freedom, and Gaussian likelihood-profile intervals for τ² with the other variance component reoptimized. These small-k intervals are illustrative; the sandwich is not a CR2 correction and its rank may be insufficient when coefficients outnumber source clusters. Profile upper limits beyond the fixed search range are recorded as unknown rather than a finite confidence bound. We report study τ² and cell ω² separately, together with generalized residual I²: 100(τ²+ω²)/(τ²+ω²+v_typ), where v_typ=(N−p)/tr(P), P=S⁻¹−S⁻¹X(X′S⁻¹X)⁻¹X′S⁻¹. The partitioned study and cell I² shares use the same denominator. These are residual, covariance-model-dependent I² quantities; a row-level Q is never represented as an independent-study heterogeneity test. See the [metafor multilevel I² formulation](https://www.metafor-project.org/doku.php/tips:i2_multilevel_multivariate).\n\n**Within-study contrasts.** The second construction cancelled study offsets before synthesis. Marginal gap contrasts used the highest and lowest CAD settings in each dose study, expressed per 10 µm; no overlapping adjacent contrasts were treated as independent. Crown contrasts used extreme actual thicknesses within identical study/material/cement/abrasion/margin strata and calculated log(force_high/force_low)/log(thickness_high/thickness_low). Conditional variance was the sum of independent arm variances divided by the squared predictor difference. No shared reference group was used across distinct strata. Six crown contrasts arise from only two studies; two marginal contrasts likewise arise from only two studies. They characterize those experiments, not a universal power law. Within-study covariance across separate crown arms remains a prerequisite for this variance expression.\n\n**Support and prediction gates.** The frozen support criterion required full rank and at least ten independent studies per non-intercept moderator coefficient, consistent with the cautions in [Cochrane Chapter 10](https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-10). A transferable local dose contrast additionally required at least three independent within-study series per target region/material/setup. These criteria failed; conditional fitted numbers were retained as exploratory rather than relabelled confirmatory. Leave-one-source-family-out predictions were compared with two explicitly declared engineering proxies: measured gap equals internal CAD spacer, and crown force scales as thickness² with a study-balanced training-only geometric calibration. The frozen prediction criterion was a study-balanced RMSE ratio ≤0.8 and conditional 95% interval coverage ≥0.90. Held studies never supplied the calibration intercept. Unsupported material levels or rank-deficient training designs returned UNKNOWN. Crown performance on the 16 scoreable groups is therefore a subset result, not performance over all 30 groups. Original observations were already accessible during the broader extraction programme, so this is retrospective source-family validation, not prospective independent laboratory validation.\n\n**Small-study effects.** We plotted descriptive funnels of one equal-weight source-family summary: marginal gap minus configured spacer, and mean log crown force across eligible arms. Their SE used the perfect-positive-correlation bound on the equal-weight arm average, since empirical covariance was unavailable. Egger regression of standardized summary on precision was computed only as an explicitly exploratory diagnostic. It was not interpreted as evidence for presence or absence of publication bias: k=9 and k=7, heterogeneous target quantities, inherited selection and unmeasured covariance violate its usual inferential setting. [Cochrane Chapter 13](https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-13) requires caution with low study counts and distinguishes funnel asymmetry from publication bias. No trim-and-fill correction or selection model was fitted.\n\n**Computation and verification.** All analyses use local data and run with at most four CPU threads. The dense inverse/determinant REML objective and external [statsmodels GLS](https://www.statsmodels.org/stable/generated/statsmodels.regression.linear_model.GLS.html) were evaluated on the same actual observations/covariance; the external GLS check covers coefficients and known-variance covariance at the fitted V, not independent REML optimization. Controls included deliberate wrong hashes/cells/estimates, rank aliases, endpoint reconstruction, offset/scale cancellation and perturbation of the fixture alias. These checks verify implementation and arithmetic, not physical transfer or independent evidence extraction. Code, raw snapshots, source hashes, costs, exclusions, scripts and figures are provided. A replay changed the first R1 result JSON before its exact predecessor bytes were archived; LINEAGE_DRIFT records this limitation. Source and protocol hashes remain intact. Later replays archive outputs before rerunning.\n\n**Remaining submission requirements.** Complete and report systematic retrieval/screening for the currently unassessed records; independently duplicate at least 20% of extraction (40 of 197 cells), resolve all SD/sample-unit definitions and source/product conflicts; perform a tailored laboratory risk-of-bias assessment; expand independent dose and fixture replication. Until then, this is a methods/analysis draft with explicit unknowns, not a submission-ready systematic meta-analysis.\n"
